// Generated from src/registry/sources/control-ui/recipes/spinner.css by scripts/gen-knob-contracts.ts — run `bun run sync:knobs`.
export const spinnerKnobs = ["--cui-spinner-foreground"] as const;
export type SpinnerKnobStyle = Partial<Record<(typeof spinnerKnobs)[number], string>>;

@layer components {
  :where([data-control-family="spinner"][data-slot="root"]) {
    --cui-spinner-foreground: var(--muted-foreground);
    color: var(--cui-spinner-foreground);
  }

  :where([data-control-family="spinner"][data-slot="indicator"]) {
    inline-size: calc(var(--spacing) * 4);
    block-size: calc(var(--spacing) * 4);
    animation: spin calc(var(--duration-slow) * 3.333) linear infinite;
  }

  :where([data-control-family="spinner"][data-slot="indicator"][data-size="xs"]) {
    inline-size: calc(var(--spacing) * 3);
    block-size: calc(var(--spacing) * 3);
  }

  :where([data-control-family="spinner"][data-slot="indicator"][data-size="md"]) {
    inline-size: calc(var(--spacing) * 5);
    block-size: calc(var(--spacing) * 5);
  }

  :where([data-control-family="spinner"][data-slot="indicator"][data-size="lg"]) {
    inline-size: calc(var(--spacing) * 6);
    block-size: calc(var(--spacing) * 6);
  }
}

@property --cui-spinner-foreground {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

import { Loader2 } from "lucide-react";
import type { ComponentProps, CSSProperties } from "react";
import type { ControlSize } from "@/components/control-ui/control-variants";
import type { SpinnerKnobStyle } from "@/components/control-ui/knob-contracts/spinner-knobs";
import { cn } from "@/components/control-ui/lib/cn";

export type SpinnerProps = Omit<
  ComponentProps<"span"> & {
    size?: ControlSize;
  },
  "style"
> & { style?: CSSProperties & SpinnerKnobStyle };

// Deliberately outside motion kill-switch — loader must keep turning under reduced motion.
export function Spinner({ size = "sm", className, ...props }: SpinnerProps) {
  return (
    <span
      role="status"
      data-control-ui="spinner"
      data-control-family="spinner"
      data-slot="root"
      className={cn("inline-flex", className)}
      {...props}
    >
      <Loader2 aria-hidden="true" data-control-ui="spinner" data-control-family="spinner" data-slot="indicator" data-size={size} />
      <span className="sr-only">Loading</span>
    </span>
  );
}
